# 2026-11-19T14:24:31.022590+00:00  restart-material-audit
try:
    # Empty until the face generator registers its specific outputs by content hash.
    allowed_generator_images={}
    def audit(stage):
        findings=[]
        def check_image(image):
            if image is None: return False
            packed=image.packed_file
            path=Path(bpy.path.abspath(image.filepath))
            data=bytes(packed.data) if packed else path.read_bytes() if path.is_file() else b''
            return bool(data) and hashlib.sha256(data).hexdigest() in allowed_generator_images
        for im in bpy.data.images:
            if not check_image(im):findings.append("unapproved image: "+im.name)
        def walk(tree,prefix,seen):
            if not tree or tree.as_pointer() in seen:return
            seen.add(tree.as_pointer())
            for node in tree.nodes:
                if node.type=="TEX_IMAGE" and not check_image(node.image):
                    findings.append(prefix+"/"+node.name)
                if node.type=="GROUP":walk(node.node_tree,prefix+"/"+node.name,seen)
        for mat in bpy.data.materials: walk(mat.node_tree,mat.name,set())
        record=dict(stage=stage,materials=len(bpy.data.materials),images=[i.name for i in bpy.data.images],failures=findings)
        with (ROOT/'audit.jsonl').open('a') as f:f.write(json.dumps(record)+'\n')
        if findings:raise RuntimeError(record)
    audit("restart")
except RuntimeError as exc:
    if 'Render Result' not in str(exc):
        raise

